     "title": "全美25州提起诉讼 反对美政府最新关税措施",
     "url": "http://finance.eastmoney.com/news/1351,202608043830160644.html",
     "time": "08-04 03:11",
     "ts": 1785784261,
     "summary": "央视记者当地时间8月3日获悉，法庭文件显示，美国有25个州提起诉讼，反对美政府最新关税措施。 美国纽约州总检察长宣布，由民主党人领导的25个美国州于当日提起诉讼，起诉美国政府。这些州主张，总统针对来自60个贸易伙伴的商品征收最新一轮关税的举措，超出了其对进口商品征税的法定权限。 总检察长称，最新关税只是为了替代那些已被美国最高法院否决的关税措施。新关税范围宽泛得不合法，且绕过了法律规定的针对特定国家的调查程序。（文章来源：央视新闻客户端）",
